//! Compare bounded open prefix to ten retained original rows.
use spore_core::cell_stream_open_prefix_v1::{project,Branch};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native rows")).unwrap();assert_eq!(b.len(),400);for i in 0..10{let k=i%5;let active=u32::from(k==0);let external=u32::from(k==4);let initialized=u8::from(k==3);let x=project(active,external,u8::from(k==1),initialized,1,0xa5a5a5a5,true).unwrap();let (ret,trap)=match x.branch{Branch::Active=>(0,0),Branch::Deferred=>(1,0),Branch::Disabled=>(0,2),Branch::OpenPending=>(0,1),Branch::ExternalPending=>(0,3)};let r=&b[i*40..(i+1)*40];assert_eq!((w(r,0),w(r,4),w(r,8),w(r,12),w(r,16),w(r,20)),(ret,trap,active,x.field_18,initialized as u32,external));let fp=w(r,24);assert_eq!(fp&0xffff,if i>=5{0x37f}else{0x27f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,28)&!0x3f,0x1f80);assert_eq!((w(r,32),w(r,36)),(0xc0dec0de,0xa5a5a5a5));}println!("matched ten source open-prefix rows; file/external paths trapped");}
